import{j as e}from"./blog-pages-CSFOXFVG.js";import{M as i}from"./MethodCoursePage-DLTkqR6H.js";const a={slug:"paut-level-2-training-course",seoTitle:"PAUT Level 2 Training Course — Phased Array UT Certification | Atlantis NDT",seoDescription:"PAUT Level 2 training course: phased array ultrasonic testing for weld inspection and corrosion mapping. SNT-TC-1A/NAS 410 pathway. Online + on-site + hybrid delivery. Free consultation.",keywords:"PAUT Level 2 training course, phased array ultrasonic testing certification, PAUT certification, PAUT Level II course, phased array UT training",h1:"PAUT Level 2 Training Course",badgeLabel:"Phased Array UT Level II Certification",heroSubtitle:"Phased Array Ultrasonic Testing (PAUT) Level II training — beam steering, sectorial scanning, encoded data acquisition and weld/corrosion-mapping technique, built on a conventional UT foundation.",methodName:"Phased Array Ultrasonic Testing (PAUT)",levelLabel:"Level II",hoursLabel:"≈80 classroom hours for the Level II base, plus dedicated PAUT-specific practical hours beyond conventional UT — actual hours depend on your prior UT certification.",stats:[{label:"Certification Level",value:"Level II"},{label:"Typical Base Hours",value:"≈80 hrs"},{label:"Recert Cycle",value:"5 Years"},{label:"Delivery",value:"Online + On-site"}],overview:["Phased Array Ultrasonic Testing (PAUT) uses a probe made of many small elements, each fired with a precisely controlled time delay, to electronically steer and focus an ultrasonic beam without moving the probe. That lets an inspector cover a weld cross-section in a single pass, display it as a sectorial (S-scan) image, and record encoded, reviewable data — capabilities conventional single-element UT does not have.","PAUT has become the primary weld-inspection method on many fabrication and pipeline codes precisely because it can match or exceed radiographic testing's flaw-detection performance without a radiation exclusion zone, and because encoded scans produce a permanent, auditable record rather than a one-time reading.","This PAUT Level 2 training course assumes a conventional UT Level II foundation and builds the phased-array-specific layer on top of it: probe and wedge selection, focal-law setup, sectorial scanning, encoded acquisition, and the zonal-discretization technique used for pipeline girth welds and pressure-vessel seams. Delivered ASNT NDT Level III-led, online + on-site + hybrid."],highlightTitle:"PAUT vs Conventional UT",highlightBody:"Conventional UT uses a single fixed-angle beam and requires the operator to physically move the probe to cover the weld volume. PAUT electronically steers and focuses the beam through dozens of angles from a stationary probe position, producing a real-time cross-sectional image and an encoded, storable record — faster coverage, better documentation, and often better flaw characterization.",curriculum:["Array probe physics and beam formation","Focal laws and sectorial (S-scan) beam steering","Wedge selection and delay-law calibration","Encoded scanning and positioning encoders","Sensitivity and Time-Corrected Gain (TCG) calibration","Weld inspection using zonal discretization technique","Corrosion mapping (C-scan) for plate and pipe","Software-based data analysis and defect sizing","Code acceptance criteria per ASME Section V Article 4 and AWS D1.1 Annex","Reporting and comparison against RT-based acceptance criteria"],pathwaySteps:[{title:"Confirm UT prerequisite",detail:"Conventional UT Level II certification (or equivalent documented experience) is the typical entry point for PAUT — the phased-array layer builds on existing ultrasonic fundamentals rather than replacing them."},{title:"PAUT-specific theory and practical",detail:"Complete online modules on array physics, focal laws and encoded scanning, then hands-on practical covering probe/wedge selection, calibration and zonal scan-plan execution."},{title:"Practical demonstration and exam",detail:"Demonstrate scan-plan development, calibration, and defect detection/sizing on representative weld or plate samples, per your employer's written practice or accredited scheme exam."},{title:"Certification issued and documented",detail:"PAUT Level II qualification is recorded alongside your base UT certification, training hours, and vision-test results."},{title:"5-year recertification cycle",detail:"PAUT qualification is renewed on the same 5-year SNT-TC-1A/CP-189 cycle as your base UT certification, with the annual vision test tracked separately."}],faqs:[{question:"Do I need conventional UT certification before taking PAUT Level 2?",answer:"Yes — PAUT Level II training assumes a conventional UT Level II foundation (or documented equivalent experience). The course builds the phased-array-specific skills — beam steering, encoded scanning, sectorial interpretation — on top of that base rather than teaching ultrasonic fundamentals from scratch."},{question:"Is PAUT replacing radiographic testing (RT)?",answer:"On many codes and applications, yes — PAUT is increasingly specified as the primary weld-inspection method because it avoids RT's radiation exclusion zone and produces an encoded, reviewable record. It hasn't fully replaced RT everywhere; some codes and client specifications still require RT or a combination of methods, which is part of what this course covers."},{question:"What industries use PAUT most?",answer:"Pipeline girth-weld inspection, pressure vessel and structural steel fabrication, and increasingly power generation and petrochemical turnaround inspection, where fast, high-integrity weld coverage with a permanent digital record is valuable."},{question:"Is the PAUT course delivered online?",answer:"Theory and software-analysis modules are delivered online. Probe handling, calibration and scan-plan execution require hands-on equipment time, so the practical component is delivered on-site or in a blended format."},{question:"How does TOFD relate to PAUT?",answer:"TOFD (time-of-flight diffraction) is often paired with PAUT for pipeline and pressure-vessel weld inspection — PAUT provides volumetric coverage and imaging, while TOFD adds precise flaw depth-sizing. See our dedicated TOFD training and certification course."}],relatedLinks:[{to:"/asnt-level-2-ut-online-course",label:"ASNT Level 2 UT Online Course",desc:"Conventional UT foundation required before PAUT"},{to:"/tofd-training-certification-course",label:"TOFD Training & Certification",desc:"Often paired with PAUT for weld depth-sizing"},{to:"/asnt-certification",label:"ASNT Certification Guide",desc:"Full Level I/II/III pathway across all methods"}],courseName:"PAUT Level II Phased Array Ultrasonic Testing Course",courseDescription:"Phased Array Ultrasonic Testing Level II training covering beam steering, sectorial scanning, encoded data acquisition, corrosion mapping and weld-inspection technique per ASME Section V Article 4 and AWS D1.1 Annex.",courseTeaches:"Phased array probe and wedge selection, beam steering and focusing, sectorial and encoded scanning, S-scan interpretation, and corrosion-mapping / weld-inspection technique",coursePrerequisites:"Conventional UT Level II certification (or documented equivalent experience) plus current vision screening",educationalCredentialAwarded:"Level II Phased Array Ultrasonic Testing certificate of training completion",educationalLevel:"Professional",durationISO:"PT80H",articleHeadline:"PAUT Level 2 Training Course: Certification Pathway & What's Covered",articleDescription:"What PAUT Level 2 training covers, why phased array replaces conventional UT for weld inspection on many codes, and the certification pathway building on a UT Level II base.",articleSection:"NDT Training",articleKeywords:"PAUT Level 2, phased array ultrasonic testing, PAUT certification, weld inspection"};function o(){return e.jsx(i,{data:a})}export{o as default};
